"use client";

import { useState } from "react";
import ListGroup from "react-bootstrap/ListGroup";
import ListGroupItem from "react-bootstrap/ListGroupItem";
import { Button, FormControl } from "react-bootstrap";

export default function TodoList() {
  const [todos, setTodos] = useState([
    { id: "1", title: "Learn React" },
    { id: "2", title: "Learn Node"  }]);
  const [todo, setTodo] = useState({ id: "-1", title: "Learn Mongo" });
  const addTodo = (todo: any) => {
    const newTodos = [ ...todos, { ...todo,
      id: new Date().getTime().toString() }];
    setTodos(newTodos);
    setTodo({id: "-1", title: ""});
  };
  const deleteTodo = (id: string) => {
    const newTodos = todos.filter((todo) => todo.id !== id);
    setTodos(newTodos);
  };
  const updateTodo = (todo: any) => {
    const newTodos = todos.map((item) =>
      (item.id === todo.id ? todo : item));
    setTodos(newTodos);
    setTodo({id: "-1", title: ""});
  };
  return (
    <div className="w-25" id="wd-todo-list">
      <h2>Todo List</h2>
      <ListGroup>
        <ListGroupItem>
          <div className="d-flex justify-content-between align-items-center w-100">
            <div>
              <Button variant="success" className="me-2" onClick={() => addTodo(todo)}
                      id="wd-add-todo-click"> Add </Button>
              <Button variant="warning" className="me-2" onClick={() => updateTodo(todo)}
                      id="wd-update-todo-click"> Update </Button>
            </div>
            <div className="flex-grow-1 ms-2">
              <FormControl value={todo.title}
                onChange={(e) => setTodo({ ...todo, title: e.target.value })}/>
            </div>
          </div>
        </ListGroupItem>
        {todos.map((todo) => (
          <ListGroupItem key={todo.id} className="p-0">
            <div className="d-flex justify-content-between align-items-center w-100">
              <div className="d-flex">
                <Button variant="danger" className="me-2" onClick={() => deleteTodo(todo.id)}
                        id="wd-delete-todo-click"> Delete </Button>
                <Button variant="primary" className="me-2" onClick={() => setTodo(todo)}
                        id="wd-set-todo-click"> Edit </Button>
              </div>
              <span className="ms-2">{todo.title}</span>
            </div>
          </ListGroupItem>
        ))}
      </ListGroup>
      <hr/>
    </div>);}